import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowed report types - security control
    private static final String[] VALID_TYPES = {"sales", "inventory", "audit", "compliance"};

    private boolean isValidType(String type) {
        if (type == null) return false;
        for (String valid : VALID_TYPES) {
            if (valid.equalsIgnoreCase(type.trim())) return true;
        }
        return false;
    }

    private String sanitizeDateRange(String input) {
        // Strip anything that isn't a digit, dash, or slash
        if (input == null) return "";
        return input.replaceAll("[^0-9\\-/]", "");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String department = req.getParameter("dept");

        if (!isValidType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        dateFrom = sanitizeDateRange(dateFrom);
        dateTo = sanitizeDateRange(dateTo);

        // Build query - sort column is user-controlled
        String baseQuery = "SELECT id, title, amount, created_at, department FROM reports "
                + "WHERE report_type = ? AND created_at BETWEEN ? AND ?";

        if (department != null && !department.isEmpty()) {
            // Parameterized - safe
            baseQuery += " AND department = ?";
        }

        // Dynamic ORDER BY - cannot use prepared statement parameter
        if (sortCol != null && !sortCol.isEmpty()) {
            baseQuery += " ORDER BY " + sortCol;
        } else {
            baseQuery += " ORDER BY created_at DESC";
        }

        log.info("Executing report query for type=" + reportType + " dept=" + department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, reportType);
            stmt.setString(2, dateFrom);
            stmt.setString(3, dateTo);
            if (department != null && !department.isEmpty()) {
                stmt.setString(4, department);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"id\": %d, \"title\": \"%s\", \"amount\": %.2f, \"date\": \"%s\", \"dept\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at"),
                    rs.getString("department")
                ));
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
